import { useEffect, useState } from "react";
const loadStudies = async () => ["React", "TanStack Query"];
export default function Studies() { const [state, setState] = useState<{ data: string[]; error: string | null; loading: boolean }>({ data: [], error: null, loading: true }); useEffect(() => { void loadStudies().then((data) => setState({ data, error: null, loading: false })).catch((error: Error) => setState({ data: [], error: error.message, loading: false })); }, []); if (state.loading) return <p>로딩 중</p>; if (state.error) return <p role="alert">{state.error}</p>; return <p>{state.data.length}개 학습을 불러왔습니다.</p>; }

